from abc import ABC, abstractmethod
from typing import Any
from pydantic import BaseModel, Field


class GroundedAnswerResponse(BaseModel):
    """Structured response model generated by an AI Provider."""
    answer: str = Field(
        description="Clear, simple-English grounded explanation or explicit abstention notice."
    )
    insufficient_evidence: bool = Field(
        default=False,
        description="True if the provided passages lacked sufficient evidence to answer the query."
    )
    cited_chunk_ids: list[str] = Field(
        default_factory=list,
        description="List of chunk IDs referenced in the generated answer."
    )
    model_name: str = Field(
        default="",
        description="Model identifier that produced the generation."
    )
    raw_response: dict[str, Any] | None = Field(
        default=None,
        description="Optional raw payload from the provider."
    )


class AIProvider(ABC):
    """Abstract base class for all AI text generation providers."""

    @abstractmethod
    async def generate_grounded_answer(
        self,
        question: str,
        passages: list[dict],
        system_instruction: str | None = None,
    ) -> GroundedAnswerResponse:
        """
        Generate an evidence-grounded answer based strictly on the provided passages.
        Returns a structured GroundedAnswerResponse.
        """
        pass
